import random

def get_user_choice():
    """Get user's choice as input."""
    choices = ["rock", "paper", "scissors"]
    while True:
        user_choice = input("Enter your choice (rock, paper, scissors): ").lower()
        if user_choice in choices:
            return user_choice
        else:
            print("Invalid input. Please enter 'rock', 'paper', or 'scissors'.")

def get_computer_choice():
    """Generate a random computer choice."""
    return random.choice(["rock", "paper", "scissors"])

def determine_winner(user_choice, computer_choice):
    """Determine the winner based on user and computer choices."""
    if user_choice == computer_choice:
        return "It's a tie!"
    elif (user_choice == "rock" and computer_choice == "scissors") or \
         (user_choice == "paper" and computer_choice == "rock") or \
         (user_choice == "scissors" and computer_choice == "paper"):
        return f"You win! Computer chose {computer_choice.capitalize()}."
    else:
        return f"Computer wins! You chose {user_choice.capitalize()}, " \
               f"but the computer chose {computer_choice.capitalize()}."

if __name__ == "__main__":
    user_choice = get_user_choice()
    computer_choice = get_computer_choice()
    print(determine_winner(user_choice, computer_choice))
```

This program will run in an infinite loop, allowing the user to play multiple rounds of Rock, Paper, Scissors.
